    public sealed class DesktopButton : Button {
        bool hover;
        public DesktopButton(){SetStyle(ControlStyles.UserPaint|ControlStyles.AllPaintingInWmPaint|ControlStyles.OptimizedDoubleBuffer,true);UseMnemonic=false;}
        protected override void OnMouseEnter(EventArgs e){hover=true;Invalidate();base.OnMouseEnter(e);}
        protected override void OnMouseLeave(EventArgs e){hover=false;Invalidate();base.OnMouseLeave(e);}
        protected override void OnEnabledChanged(EventArgs e){Invalidate();base.OnEnabledChanged(e);}
        protected override void OnPaint(PaintEventArgs e){
            Color background=Enabled?BackColor:DesktopTheme.Card;using(var fill=new SolidBrush(background))e.Graphics.FillRectangle(fill,ClientRectangle);
            using(var border=new Pen(hover&&Enabled?DesktopTheme.Accent:Color.FromArgb(65,84,105)))e.Graphics.DrawRectangle(border,0,0,Math.Max(0,Width-1),Math.Max(0,Height-1));
            TextRenderer.DrawText(e.Graphics,Text,Font,ClientRectangle,Enabled?ForeColor:DesktopTheme.Muted,TextFormatFlags.HorizontalCenter|TextFormatFlags.VerticalCenter|TextFormatFlags.NoPrefix|TextFormatFlags.WordBreak);
            if(Focused&&ShowFocusCues)ControlPaint.DrawFocusRectangle(e.Graphics,new Rectangle(4,4,Math.Max(0,Width-8),Math.Max(0,Height-8)),ForeColor,background);
        }
    }
    public sealed class DesktopTabs : Panel {
        public readonly List<Panel> TabPages=new List<Panel>();readonly List<Button> buttons=new List<Button>();readonly Panel body=new Panel();readonly FlowLayoutPanel header=new FlowLayoutPanel();int selected=-1;
        public DesktopTabs(){Dock=DockStyle.Fill;BackColor=DesktopTheme.Background;var layout=DesktopTheme.Table(1,2);layout.RowStyles.Add(new RowStyle(SizeType.Absolute,46));layout.RowStyles.Add(new RowStyle(SizeType.Percent,100));header.Dock=DockStyle.Fill;header.WrapContents=false;body.Dock=DockStyle.Fill;layout.Controls.Add(header,0,0);layout.Controls.Add(body,0,1);Controls.Add(layout);}
        public int SelectedIndex{get{return selected;}set{if(value<0||value>=TabPages.Count)throw new ArgumentOutOfRangeException("value");selected=value;for(int i=0;i<TabPages.Count;i++){TabPages[i].Visible=i==value;buttons[i].ForeColor=i==value?DesktopTheme.Accent:DesktopTheme.Muted;buttons[i].BackColor=i==value?DesktopTheme.Card:DesktopTheme.Background;buttons[i].Invalidate();}TabPages[value].BringToFront();}}
        public void AddPage(string title,Panel page){int index=TabPages.Count;TabPages.Add(page);page.Dock=DockStyle.Fill;body.Controls.Add(page);var button=DesktopTheme.Button(title,delegate{SelectedIndex=index;});button.Width=160;button.Height=38;buttons.Add(button);header.Controls.Add(button);if(selected<0)SelectedIndex=0;else page.Visible=false;}
        protected override bool ProcessCmdKey(ref Message msg,Keys keyData){if(keyData==(Keys.Control|Keys.Tab)||keyData==(Keys.Control|Keys.Shift|Keys.Tab)){SelectedIndex=(selected+(keyData==(Keys.Control|Keys.Tab)?1:TabPages.Count-1))%TabPages.Count;return true;}return base.ProcessCmdKey(ref msg,keyData);}
    }
    public static class DesktopTheme {
        public static readonly Color Background=Color.FromArgb(14,20,29),Card=Color.FromArgb(23,32,44),Muted=Color.FromArgb(165,183,202),Accent=Color.FromArgb(81,224,187),Warning=Color.FromArgb(255,199,111);
        public static Label Label(string text,int size,Color color){return new Label{Text=text,UseMnemonic=false,Font=new Font("Segoe UI",size),ForeColor=color,Dock=DockStyle.Fill,TextAlign=ContentAlignment.MiddleLeft,AutoEllipsis=true};}
        public static Button Button(string text,EventHandler click,bool primary=false){var b=new DesktopButton{Text=text,AutoSize=false,Width=200,Height=40,Margin=new Padding(0,4,12,4),FlatStyle=FlatStyle.Flat,BackColor=primary?Accent:Card,ForeColor=primary?Background:Color.White,UseVisualStyleBackColor=false,Cursor=Cursors.Hand};b.FlatAppearance.BorderColor=Color.FromArgb(65,84,105);b.Click+=click;return b;}
        public static TableLayoutPanel Table(int columns,int rows){var t=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=columns,RowCount=rows,Margin=Padding.Empty,Padding=Padding.Empty,BackColor=Color.Transparent};return t;}
        public static Panel Box(){return new Panel{Dock=DockStyle.Fill,BackColor=Card,Padding=new Padding(18),Margin=new Padding(0,0,14,14)};}
    }
    public sealed class AxisMeter : Control {
        public int Value;public bool Centered;public string Caption="";
        public AxisMeter(){DoubleBuffered=true;Height=72;Dock=DockStyle.Fill;ForeColor=Color.White;BackColor=DesktopTheme.Card;}
        protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);int y=36,w=Math.Max(1,Width-2);using(var brush=new SolidBrush(DesktopTheme.Muted))e.Graphics.DrawString(Caption,Font,brush,0,3);using(var track=new SolidBrush(Color.FromArgb(43,58,76)))e.Graphics.FillRectangle(track,0,y,w,10);using(var fill=new SolidBrush(DesktopTheme.Accent)){
            int x=(int)(Math.Max(0,Math.Min(32767,Value))/32767.0*w);
            if(Centered)e.Graphics.FillRectangle(fill,Math.Min(w/2,x),y,Math.Max(2,Math.Abs(x-w/2)),10);else e.Graphics.FillRectangle(fill,0,y,Math.Max(2,x),10);
        }if(Centered)using(var pen=new Pen(DesktopTheme.Muted))e.Graphics.DrawLine(pen,w/2,y-5,w/2,y+15);}
    }
