            var title=DesktopTheme.Label("Your joystick",20,Color.White);title.Dock=DockStyle.None;title.Size=new Size(850,48);content.Controls.Add(title);
            identity.ForeColor=DesktopTheme.Muted;identity.Size=new Size(850,64);content.Controls.Add(identity);
            var actions=new FlowLayoutPanel{Width=850,Height=58};actions.Controls.Add(DesktopTheme.Button("USB setup & calibration",delegate{OpenCalibration();},true));actions.Controls.Add(DesktopTheme.Button("Control diagram",delegate{new ControlDiagram().Show(this);}));actions.Controls.Add(DesktopTheme.Button("Windows controller test",delegate{if(!preview)System.Diagnostics.Process.Start("control.exe","joy.cpl");}));content.Controls.Add(actions);
            var notes=DesktopTheme.Label("USB calibration\nChoose the board's COM port, capture five positions, then apply.\nImport/export and backup restore are available in the calibration window.\n\nBluetooth\nThe transport contract is designed and model-tested. Pairing and radio gameplay are not available yet.\n\nProfiles change controller response. Your simulator keeps its own button and axis bindings.",11,DesktopTheme.Muted);notes.Dock=DockStyle.None;notes.Size=new Size(850,220);notes.TextAlign=ContentAlignment.TopLeft;notes.Margin=new Padding(3,10,3,0);content.Controls.Add(notes);
            content.SizeChanged+=delegate{foreach(Control child in content.Controls)child.Width=Math.Max(300,content.ClientSize.Width-20);};
        }
