            var left=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown,WrapContents=false,AutoScroll=true};layout.Controls.Add(left,0,0);var intro=DesktopTheme.Label("Simulated controls",19,Color.White);intro.Dock=DockStyle.None;intro.Size=new Size(450,45);left.Controls.Add(intro);
            left.Controls.Add(LabLabel("Rudder / Rz"));ConfigureSlider(rudder,16384);left.Controls.Add(rudder);AddCheck(left,spring,"Spring return on release",true);rudder.MouseUp+=delegate{if(spring.Checked)rudder.Value=16384;};left.Controls.Add(LabLabel("Throttle / Slider"));ConfigureSlider(throttle,0);left.Controls.Add(throttle);
            var bs=new FlowLayoutPanel{Width=450,Height=110};string[] names={"1 · Gear","2 · Brake left","3 · Brake center","4 · Brake right"};for(int i=0;i<4;i++){int bit=1<<i;var b=DesktopTheme.Button(names[i],delegate{});b.Width=195;b.MouseDown+=delegate{buttonMask|=(byte)bit;};b.MouseUp+=delegate{buttonMask&=(byte)~bit;};b.MouseCaptureChanged+=delegate{if(!b.Capture)buttonMask&=(byte)~bit;};b.KeyDown+=delegate(object o,KeyEventArgs e){if(e.KeyCode==Keys.Space){buttonMask|=(byte)bit;e.Handled=true;}};b.KeyUp+=delegate(object o,KeyEventArgs e){if(e.KeyCode==Keys.Space){buttonMask&=(byte)~bit;e.Handled=true;}};b.LostFocus+=delegate{buttonMask&=(byte)~bit;};testButtons[i]=b;bs.Controls.Add(b);}left.Controls.Add(bs);
            var right=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown,WrapContents=false};layout.Controls.Add(right,1,0);var labTitle=DesktopTheme.Label("Transport simulation",19,Color.White);labTitle.Dock=DockStyle.None;labTitle.Size=new Size(350,45);right.Controls.Add(labTitle);AddCheck(right,usb,"USB available (simulated)",true);AddCheck(right,ble,"Bluetooth available (simulated)",true);AddCheck(right,freeze,"Freeze packets",false);AddCheck(right,demo,"Animate test axes",false);var labNote=DesktopTheme.Label("These controls generate synthetic input.\nThey are disabled while physical USB mode is selected.\n\nFreezing packets exercises stale-input handling. It does not disconnect a real device.",10,DesktopTheme.Muted);labNote.Dock=DockStyle.None;labNote.Size=new Size(345,150);right.Controls.Add(labNote);right.Controls.Add(DesktopTheme.Button("Simulation profile",delegate{OpenSimulationProfile();}));
        }
        void BuildDiagnostics(Panel page){var grid=DesktopTheme.Table(1,3);grid.RowStyles.Add(new RowStyle(SizeType.Absolute,112));grid.RowStyles.Add(new RowStyle(SizeType.Absolute,56));grid.RowStyles.Add(new RowStyle(SizeType.Percent,100));page.Controls.Add(grid);diagnostic.Dock=DockStyle.Fill;diagnostic.ForeColor=DesktopTheme.Muted;grid.Controls.Add(diagnostic,0,0);var actions=new FlowLayoutPanel{Dock=DockStyle.Fill};actions.Controls.Add(DesktopTheme.Button("Restart bridge",delegate{Guard(delegate{if(!preview)Bridge.Restart(bridge);});}));actions.Controls.Add(DesktopTheme.Button("Stop input",delegate{StopInput();}));actions.Controls.Add(DesktopTheme.Button("Copy status",delegate{Clipboard.SetText(banner.Text+Environment.NewLine+diagnostic.Text);}));grid.Controls.Add(actions,0,1);log.Dock=DockStyle.Fill;log.BackColor=DesktopTheme.Card;log.ForeColor=DesktopTheme.Muted;log.ReadOnly=true;log.BorderStyle=BorderStyle.None;grid.Controls.Add(log,0,2);}
