        void ConfigureSlider(TrackBar slider,int value){slider.Minimum=0;slider.Maximum=32767;slider.Value=value;slider.TickStyle=TickStyle.None;slider.Size=new Size(420,42);slider.SmallChange=328;slider.LargeChange=3277;slider.BackColor=DesktopTheme.Background;}
