        void Guard(Action action){try{action();}catch(Exception e){MessageBox.Show(this,e.Message,"MinimalJoystick",MessageBoxButtons.OK,MessageBoxIcon.Information);}}
        void OpenCalibration(){new HardwareUsbEditor(bridge,preview).Show(this);}
        void OpenSimulationProfile(){new ProfileEditor(profile,delegate{return new ControlsState((ushort)rudder.Value,(ushort)throttle.Value,buttonMask);},delegate(Profile p){profile=p;if(!preview)bridge.Profile(p);}).Show(this);}
        void InitializeBridge(){
            Guard(delegate{if(File.Exists(Profile.DefaultPath))profile=Profile.Load(Profile.DefaultPath);});
            Guard(delegate{Snapshot state=bridge.Read();if(BridgeLink.Alive(state)&&state.BridgeVersion<3)Bridge.Restart(bridge);if(!BridgeLink.Alive(bridge.Read()))bridge.ConfigureHardware(File.Exists(HardwareProfile.DefaultPath)?HardwareProfile.Load(HardwareProfile.DefaultPath):new HardwareProfile());});
            bridge.Profile(profile);bridge.Command(3,new ControlsState(16384,0,0));if(!BridgeLink.Alive(bridge.Read()))Guard(delegate{Bridge.Start();});
        }
        void SetupTray(){tray.Icon=SystemIcons.Application;tray.Text="MinimalJoystick";var menu=new ContextMenuStrip();menu.Items.Add("Open MinimalJoystick",null,delegate{Show();WindowState=FormWindowState.Normal;Activate();});menu.Items.Add("Stop input",null,delegate{StopInput();});menu.Items.Add("Exit and stop input",null,delegate{ExitAndStop();});tray.ContextMenuStrip=menu;tray.DoubleClick+=delegate{Show();Activate();};tray.Visible=true;}
        void StopInput(){if(!preview&&bridge!=null){Snapshot s=bridge.Read();bridge.Command(16,new ControlsState(16384,s.Output.Throttle,0));}buttonMask=0;}
        void ExitAndStop(){StopInput();exiting=true;Close();}
        void UpdateLive(){
            Snapshot state;HardwareProfile hp;HardwareSnapshot hw;
            if(preview){state=new Snapshot{Connected=true,Transport=3,BridgeVersion=3,Heartbeat=DateTime.UtcNow.Ticks,Reports=4380,Output=new ControlsState(21000,19000,2)};hp=new HardwareProfile{Enabled=true,Calibrated=true,Port="COM7"};hw=new HardwareSnapshot{Time=DateTime.UtcNow.Ticks,Status="Sample readings",Frame=new UsbFrame{Angle=235,Adc=2450,Buttons=2,Flags=31,Millivolts=4030,Soc256=19200}};}
            else{
                state=bridge.Read();hp=bridge.ReadHardwareConfig();hw=bridge.ReadHardware();
                if((state.Flags&16)==0){int flags=(usb.Checked?1:0)|(ble.Checked?2:0)|(freeze.Checked?4:0)|(demo.Checked?8:0);bridge.Command(flags,new ControlsState((ushort)rudder.Value,(ushort)throttle.Value,buttonMask));}
            }
            bool alive=BridgeLink.Alive(state),stopped=(state.Flags&16)!=0;string source=state.Transport==3?"USB · physical":state.Transport==1?"USB · simulated":state.Transport==2?"Bluetooth · simulated":"Waiting for fresh input";
            banner.Text=preview?"DESIGN PREVIEW · Sample data only. No driver, USB port or Bluetooth connection is opened.":stopped?"Input stopped · Open Diagnostics to restart the bridge.":!alive?"Bridge offline · Open Diagnostics to restart it.":!state.Connected?"Windows controller unavailable · The preview is visible, but games receive no input.":hp.Enabled&&state.Transport!=3?"USB needs attention · Open calibration for connection and sensor details.":hp.Enabled?"MinimalJoystick is ready · USB input is feeding your Windows controller.":"Test mode · Simulated input is feeding your Windows controller.";
            banner.ForeColor=preview||!alive||stopped||!state.Connected||hp.Enabled&&state.Transport!=3?DesktopTheme.Warning:DesktopTheme.Accent;
            connection.Text=source+Environment.NewLine+(hp.Enabled?"Port "+hp.Port:"Laboratory input selected")+Environment.NewLine+"Bluetooth gameplay: not implemented";
            battery.Text=hw.Frame!=null&&(hw.Frame.Flags&4)!=0?string.Format("{0}battery: {1:F0}%\n{2:F2} V · device estimate",hw.Fresh?"Reported ":"Last reported ",hw.Frame.Soc256/256.0,hw.Frame.Millivolts/1000.0):"Battery unavailable\nA valid device reading is required.";
            if(hw.Frame!=null&&!hw.Fresh)battery.Text+="\nInput is stale.";
            calibration.Text=hp.Enabled?(hp.Calibrated?"Saved USB calibration\nDevice response only; bindings stay in your simulator.":"Five captures needed\nOpen USB setup to calibrate."):"Simulation profile active\nPhysical USB uses separate calibration.";
            identity.Text="Windows controller: MinimalJoystick\nSerial: MJ-PROTOTYPE-0001 · 2 axes · 4 buttons\nThe same virtual controller is used across input sources.";
            rudderMeter.Value=state.Output.Rudder;rudderMeter.Caption=string.Format("RUDDER   {0:+0;-0;0}%",(state.Output.Rudder-16384)/163.84);rudderMeter.Invalidate();throttleMeter.Value=state.Output.Throttle;throttleMeter.Caption=string.Format("THROTTLE   {0:F0}%",state.Output.Throttle/327.67);throttleMeter.Invalidate();
            rawValues.Text=hp.Enabled&&hw.Frame!=null?string.Format("Raw angle {0} · ADC {1} · {2}",hw.Frame.Angle,hw.Frame.Adc,hw.Fresh?"fresh input":"stale input"):"Move the simulated controls in Test laboratory.";
            for(int i=0;i<4;i++){bool down=(state.Output.Buttons&(1<<i))!=0;indicators[i].BackColor=down?DesktopTheme.Accent:Color.FromArgb(35,47,62);indicators[i].ForeColor=down?DesktopTheme.Background:DesktopTheme.Muted;testButtons[i].Enabled=!hp.Enabled;}
            rudder.Enabled=throttle.Enabled=usb.Enabled=ble.Enabled=freeze.Enabled=demo.Enabled=spring.Enabled=!hp.Enabled;if(hp.Enabled)buttonMask=0;
            diagnostic.Text=string.Format("Bridge: {0} · HID: {1} · source: {2}\nReports attempted: {3}\nUSB: {4}\nNo telemetry is uploaded. Copy status only when you choose to share it.",stopped?"stopped":alive?"running":"offline",state.Connected?"connected":"unavailable",source,state.Reports,hw.Status??"Not selected");
            string transition=banner.Text+" | "+source;if(transition!=previous){log.AppendText(DateTime.Now.ToString("HH:mm:ss")+"  "+transition+Environment.NewLine);previous=transition;if(log.TextLength>12000)log.Text=log.Text.Substring(log.TextLength-6000);}
        }
        public static void SavePreviews(string directory){Directory.CreateDirectory(directory);using(var form=new Prototype(true)){form.Show();Application.DoEvents();for(int i=0;i<form.tabs.TabPages.Count;i++){form.tabs.SelectedIndex=i;Application.DoEvents();using(var image=new Bitmap(form.Width,form.Height)){form.DrawToBitmap(image,new Rectangle(Point.Empty,form.Size));image.Save(Path.Combine(directory,"desktop-"+i+".png"));}}form.tabs.SelectedIndex=0;form.ClientSize=new Size(920,740);Application.DoEvents();using(var image=new Bitmap(form.Width,form.Height)){form.DrawToBitmap(image,new Rectangle(Point.Empty,form.Size));image.Save(Path.Combine(directory,"desktop-compact.png"));}using(var wizard=new HardwareUsbEditor(null,true)){wizard.Show();Application.DoEvents();using(var image=new Bitmap(wizard.Width,wizard.Height)){wizard.DrawToBitmap(image,new Rectangle(Point.Empty,wizard.Size));image.Save(Path.Combine(directory,"calibration.png"));}}}}
    }
